mapper.select:
insert into document_base (
    seq
    ,up_seq
    ,file_master_seq
    ,title
    ,contents
    ,reg_dttm
    ,reg_id
) values (
    nextval('doc_seq')
    ,#{upSeq} 
    ,#{fileMasterSeq} 
    ,#{title}
    ,#{contents}
    ,NOW()
    ,coalesce(#{regId},'system') /* regId might not be in DocumentDto, default to system or add to DTO */
)
RETURNING seq

mapper.update:
update 
    document_base
set
    title = #{title}
    ,contents = #{contents}
    ,mod_id = coalesce(#{modId},'system') /* modId might not be in DocumentDto, default to system or add to DTO */
    ,mod_dttm = NOW()

    ,file_master_seq = #{fileMasterSeq}

where
    1=1
    and seq = #{seq}

mapper.select:
select file_master_seq, file_seq, file_name, file_path, file_type, file_size, file_ext, reg_dttm /* document_seq is not in document_file table based on previous file repository xml */ from document_file where 1=1
and file_master_seq = #{fileMasterSeq}
order by reg_dttm desc
